import json, pathlib, re, subprocess
home=pathlib.Path.home()
print('=== REGISTRY_RAW_RELEVANT ===')
reg=json.loads((home/'Library/Application Support/local-agent/repositories.json').read_text())
for item in reg.get('repositories',[]):
    print(json.dumps({k:item.get(k) for k in ('id','repository','control_dir','work_dir','checkpoints_dir','control_branch','default_branch','enabled','legacy_workspace')}, sort_keys=True))
print('=== CHROME_EXTENSION_MATCHES ===')
chrome=home/'Library/Application Support/Google/Chrome'
profiles=[p for p in chrome.iterdir() if p.is_dir() and (p.name=='Default' or p.name.startswith('Profile '))] if chrome.exists() else []
matches=[]
for profile in sorted(profiles):
    pref=profile/'Preferences'
    if not pref.exists(): continue
    try: data=json.loads(pref.read_text())
    except Exception as e:
        print(f'PREF_READ_ERROR profile={profile.name} err={e!r}'); continue
    settings=((data.get('extensions') or {}).get('settings') or {})
    for ext_id, ext in settings.items():
        path=str(ext.get('path') or '')
        manifest=ext.get('manifest') or {}
        name=str(manifest.get('name') or '')
        if 'local-agent/chat_bridge' in path or 'Local Agent Chat Bridge' in name or path.endswith('/chat_bridge'):
            rec={'profile':profile.name,'extension_id':ext_id,'path':path,'name':name,'version':manifest.get('version'),'state':ext.get('state'),'location':ext.get('location')}
            matches.append((profile,ext_id,rec))
            print(json.dumps(rec,sort_keys=True))
print('=== BRIDGE_STORAGE_STRINGS ===')
if not matches:
    print('NO_MATCHING_UNPACKED_EXTENSION')
for profile,ext_id,rec in matches:
    storage=profile/'Local Extension Settings'/ext_id
    print(f'STORAGE profile={profile.name} id={ext_id} path={storage} exists={storage.exists()}')
    if not storage.exists(): continue
    chunks=[]
    for f in sorted(storage.iterdir()):
        if not f.is_file(): continue
        try: blob=f.read_bytes()
        except Exception: continue
        for run in re.findall(rb'[\x20-\x7e]{16,}',blob):
            txt=run.decode('utf-8','replace')
            if any(key in txt for key in ('bridgeState','repositoryId','chat-','growbox-ml-controller','esp32-c6-zigbee','C6_zigbee','Stage27C')):
                if txt not in chunks: chunks.append(txt)
    print(f'MATCHING_STRINGS={len(chunks)}')
    for i,txt in enumerate(chunks[:80],1):
        print(f'STR[{i}]={txt[:16000]}')
